package com.bank.barrier;

import java.util.List;
import java.util.concurrent.BrokenBarrierException;
import java.util.concurrent.CyclicBarrier;
import java.util.logging.Logger;

// Mirrors Spark's BarrierTaskContext: a global barrier() + knowledge of all peers.
class BarrierTaskContext {
    private static final Logger log = Logger.getLogger(BarrierTaskContext.class.getName());

    private final CyclicBarrier barrier;
    private final List<String> peerInfos;  // host:port of every task (for all-reduce)

    BarrierTaskContext(CyclicBarrier barrier, List<String> peerInfos) {
        this.barrier = barrier;
        this.peerInfos = peerInfos;
    }

    // All tasks block here until EVERY task reaches it — a global sync point.
    void barrier(int taskId) throws BrokenBarrierException, InterruptedException {
        log.fine(() -> "task " + taskId + " reached barrier, waiting for all peers");
        barrier.await();
    }

    List<String> getTaskInfos() { return peerInfos; }
}
