package com.bank.barrier;

import java.util.concurrent.Callable;
import java.util.logging.Logger;

// Simulates one distributed-training worker doing all-reduce at each step.
class TrainingTask implements Callable<Integer> {
    private static final Logger log = Logger.getLogger(TrainingTask.class.getName());

    private final int taskId;
    private final BarrierTaskContext ctx;
    private final int steps;
    private final int failAtStep;   // -1 = never fail

    TrainingTask(int taskId, BarrierTaskContext ctx, int steps, int failAtStep) {
        this.taskId = taskId;
        this.ctx = ctx;
        this.steps = steps;
        this.failAtStep = failAtStep;
    }

    @Override public Integer call() throws Exception {
        log.info(() -> "Worker " + taskId + " started. Peers = " + ctx.getTaskInfos());
        for (int step = 1; step <= steps; step++) {
            if (step == failAtStep) {
                log.severe("Worker " + taskId + " CRASHED at step " + step
                        + " — peers would deadlock at all-reduce → whole stage must restart");
                throw new RuntimeException("worker " + taskId + " failed");
            }
            final int s = step;
            log.fine(() -> "Worker " + taskId + " computed gradients for step " + s);
            ctx.barrier(taskId);  // all-reduce sync: everyone exchanges gradients here
            log.info(() -> "Worker " + taskId + " all-reduce complete for step " + s);
        }
        return taskId;
    }
}
