package com.bank.barrier;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.BrokenBarrierException;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.logging.Logger;

// Gang scheduler: launch ALL tasks together or refuse; restart WHOLE stage on any failure.
class BarrierScheduler {
    private static final Logger log = Logger.getLogger(BarrierScheduler.class.getName());

    private final int availableSlots;

    BarrierScheduler(int availableSlots) { this.availableSlots = availableSlots; }

    // Runs one barrier stage attempt. Returns true if all tasks succeeded.
    boolean runBarrierStage(int numWorkers, int steps, int failWorker, int failStep) {
        if (numWorkers > availableSlots) {
            log.severe(() -> "Cannot start barrier stage: need " + numWorkers
                    + " slots but only " + availableSlots + " available (all-or-none)");
            return false;
        }

        List<String> peers = new ArrayList<>();
        for (int i = 0; i < numWorkers; i++) peers.add("worker-host-" + i + ":7000" + i);

        CyclicBarrier barrier = new CyclicBarrier(numWorkers);
        BarrierTaskContext ctx = new BarrierTaskContext(barrier, peers);
        ExecutorService pool = Executors.newFixedThreadPool(numWorkers);
        log.info(() -> "Gang-scheduling " + numWorkers + " tasks simultaneously");

        try {
            List<Future<Integer>> futures = new ArrayList<>();
            for (int i = 0; i < numWorkers; i++) {
                int fs = (i == failWorker) ? failStep : -1;
                futures.add(pool.submit(new TrainingTask(i, ctx, steps, fs)));
            }
            for (Future<Integer> f : futures) f.get(); // any failure throws here
            log.info("Barrier stage SUCCEEDED — all workers finished training together");
            return true;
        } catch (ExecutionException e) {
            barrier.reset(); // break the barrier so stuck peers stop waiting
            log.severe(() -> "A task failed → RESTARTING THE WHOLE STAGE (not just the failed task)");
            return false;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return false;
        } finally {
            pool.shutdownNow();
        }
    }
}
