package com.bank.barrier;

import java.util.logging.Logger;

public class BarrierDemo {
    private static final Logger log = Logger.getLogger(BarrierDemo.class.getName());

    public static void main(String[] args) {
        BarrierScheduler scheduler = new BarrierScheduler(4);

        log.info("=== Attempt 1: happy path, all 4 workers train together ===");
        scheduler.runBarrierStage(4, 3, -1, -1);

        log.info("=== Attempt 2: worker 2 crashes at step 2 → whole stage restarts ===");
        boolean ok = scheduler.runBarrierStage(4, 3, 2, 2);
        if (!ok) {
            log.warning("Stage failed; scheduler would resubmit the ENTIRE stage with all workers fresh");
            log.info("=== Restart: all 4 workers launched again from scratch ===");
            scheduler.runBarrierStage(4, 3, -1, -1);
        }

        log.info("=== Attempt 3: ask for 8 workers but only 4 slots → cannot start ===");
        scheduler.runBarrierStage(8, 3, -1, -1);
    }
}
